1234→func TestEnsureMetadataBranch_DoesNotFastForwardWhenBehind(t *testing.T) {
1235→	t.Parallel()
1236→
1237→	bareDir := initBareWithMetadataBranch(t)
1238→	cloneDir, run := cloneWithConfig(t, bareDir)
1239→
1240→	// Create local branch from remote (normal state)
1241→	repo, err := git.PlainOpen(cloneDir)
1242→	if err != nil {
1243→		t.Fatalf("failed to open repo: %v", err)
1244→	}
1245→	if err := EnsureMetadataBranch(repo); err != nil {
1246→		t.Fatalf("first EnsureMetadataBranch() failed: %v", err)
1247→	}
1248→
1249→	// Remember current local hash
1250→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1251→	localBefore, err := repo.Reference(refName, true)
1252→	if err != nil {
1253→		t.Fatalf("local branch not found: %v", err)
1254→	}
1255→
1256→	// Add a second checkpoint to the remote (simulates another machine pushing)
1257→	run("checkout", paths.MetadataBranchName)
1258→	secondDir := filepath.Join(cloneDir, "cd", "ef01234567")
1259→	if err := os.MkdirAll(secondDir, 0o755); err != nil {
