1267→	}
1268→	run("add", ".")
1269→	run("commit", "-m", "Checkpoint: cdef01234567")
1270→	run("push", "origin", paths.MetadataBranchName)
1271→
1272→	// Reset local branch back to the old commit (local is now behind remote)
1273→	if err := repo.Storer.SetReference(
1274→		plumbing.NewHashReference(refName, localBefore.Hash()),
1275→	); err != nil {
1276→		t.Fatalf("failed to reset ref: %v", err)
1277→	}
1278→
1279→	// Re-open to clear caches
1280→	repo, err = git.PlainOpen(cloneDir)
1281→	if err != nil {
1282→		t.Fatalf("failed to reopen repo: %v", err)
1283→	}
1284→
1285→	if err := EnsureMetadataBranch(repo); err != nil {
1286→		t.Fatalf("second EnsureMetadataBranch() failed: %v", err)
1287→	}
1288→
1289→	// EnsureMetadataBranch no longer fast-forwards diverged branches (handled by push path).
1290→	// Local should be unchanged since it has real data and shares ancestry with remote.
1291→	localAfter, err := repo.Reference(refName, true)
1292→	if err != nil {
1293→		t.Fatalf("local branch not found: %v", err)
1294→	}
