1300→// buildCommittedTree creates a git tree with the sharded committed checkpoint layout
1301→// used by entire/checkpoints/v1. files is a map of path -> content relative to the tree root.
1302→// Example: {"a3/b2c4d5e6f7/0/prompt.txt": "Hello"} creates the nested directory structure.
1303→func buildCommittedTree(t *testing.T, files map[string]string) *object.Tree {
1304→	t.Helper()
1305→	dir := t.TempDir()
1306→	repo, err := git.PlainInit(dir, false)
1307→	if err != nil {
1308→		t.Fatalf("failed to init repo: %v", err)
1309→	}
1310→
1311→	for path, content := range files {
1312→		absPath := filepath.Join(dir, path)
1313→		if err := os.MkdirAll(filepath.Dir(absPath), 0o755); err != nil {
1314→			t.Fatalf("failed to create directory for %s: %v", path, err)
1315→		}
1316→		if err := os.WriteFile(absPath, []byte(content), 0o644); err != nil {
1317→			t.Fatalf("failed to write %s: %v", path, err)
1318→		}
1319→	}
1320→
1321→	wt, err := repo.Worktree()
1322→	if err != nil {
1323→		t.Fatalf("failed to get worktree: %v", err)
1324→	}
1325→	if _, err := wt.Add("."); err != nil {
1326→		t.Fatalf("failed to add files: %v", err)
1327→	}
1328→	commitHash, err := wt.Commit("test tree", &git.CommitOptions{
1329→		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
1330→	})
1331→	if err != nil {
1332→		t.Fatalf("failed to commit: %v", err)
1333→	}
1334→
1335→	commit, err := repo.CommitObject(commitHash)
1336→	if err != nil {
1337→		t.Fatalf("failed to get commit: %v", err)
1338→	}
1339→	tree, err := commit.Tree()
1340→	if err != nil {
1341→		t.Fatalf("failed to get tree: %v", err)
1342→	}
1343→	return tree
1344→}
