// sessionIdentity holds the sparse set of fields decoded from a session metadata
// file by decodeSessionIdentity. Kept lightweight to avoid allocating the full
// CommittedMetadata struct (which includes heavy nested objects like TokenUsage,
// Summary, and InitialAttribution).
type sessionIdentity struct {
	SessionID string
	Agent     types.AgentType
	CreatedAt time.Time
	IsTask    bool
	ToolUseID string
}

// decodeSessionIdentity reads only the identity/routing fields from a session
// metadata file using streaming JSON decoding.
func decodeSessionIdentity(tree *object.Tree, path string) (*sessionIdentity, error) {
	file, err := tree.File(path)
	if err != nil {
		return nil, fmt.Errorf("failed to find session metadata at %s: %w", path, err)
	}

	reader, err := file.Reader()
	if err != nil {
		return nil, fmt.Errorf("failed to open session metadata reader: %w", err)
	}
	defer reader.Close()

	var sparse struct {
		SessionID string          `json:"session_id"`
		Agent     types.AgentType `json:"agent"`
		CreatedAt time.Time       `json:"created_at"`
		IsTask    bool            `json:"is_task"`
		ToolUseID string          `json:"tool_use_id"`
	}

	if err := json.NewDecoder(reader).Decode(&sparse); err != nil {
		return nil, fmt.Errorf("failed to decode session metadata: %w", err)
	}

	return &sessionIdentity{
		SessionID: sparse.SessionID,
		Agent:     sparse.Agent,
		CreatedAt: sparse.CreatedAt,
		IsTask:    sparse.IsTask,
		ToolUseID: sparse.ToolUseID,
	}, nil
}

