// populateCheckpointInfo fills a CheckpointInfo struct from a checkpoint's metadata.json
// using streaming JSON decoding. It reads the root summary and then decodes each session's
// metadata with a sparse struct to avoid allocating full CommittedMetadata objects.
func populateCheckpointInfo(rootTree, checkpointTree *object.Tree, info *CheckpointInfo) {
	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
	if err != nil {
		return
	}

	reader, err := metadataFile.Reader()
	if err != nil {
		return
	}
	defer reader.Close()

	var summary checkpoint.CheckpointSummary
	if err := json.NewDecoder(reader).Decode(&summary); err != nil || len(summary.Sessions) == 0 {
		return
	}

	info.CheckpointsCount = summary.CheckpointsCount
	info.FilesTouched = summary.FilesTouched
	info.SessionCount = len(summary.Sessions)

	// Read session-level metadata using streaming decoder with sparse struct.
	for i, sessionPaths := range summary.Sessions {
		if sessionPaths.Metadata == "" {
			continue
		}
		// SessionFilePaths contains absolute paths with leading "/"
		// Strip the leading "/" for tree.File() which expects paths without leading slash
		sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
		si, sErr := decodeSessionIdentity(rootTree, sessionMetadataPath)
		if sErr != nil {
			continue
		}
		info.SessionIDs = append(info.SessionIDs, si.SessionID)
		// Use first session's metadata for Agent, SessionID, CreatedAt
		if i == 0 {
			info.Agent = si.Agent
			info.SessionID = si.SessionID
			info.CreatedAt = si.CreatedAt
			info.IsTask = si.IsTask
			info.ToolUseID = si.ToolUseID
		}
	}
}

